+static int
+dissect_drda_mgrlvlls(tvbuff_t *tvb, packet_info *pinfo _U_, proto_tree *tree, void *data _U_)
+{
+    proto_tree *drda_tree_sub;
+    proto_item *ti;
+
+    gint offset = 0;
+    guint16 iParameterCP;
+    gint iLengthParam = 4;
+
+    while (tvb_reported_length_remaining(tvb, offset) >= 2)
