+        proto_tree_add_item(drda_tree_sub, hf_drda_mgrlvln, tvb, offset + 2, 2, ENC_BIG_ENDIAN);
+        offset += iLengthParam;
+    }
+
+    return tvb_captured_length(tvb);
+}
